import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ChevronLeft, Calendar, ChevronDown, X } from 'lucide-react';
import './Transport.css';

const Transport = () => {
  const navigate = useNavigate();
  // view: 'main' (显示记录/空状态), 'booking' (显示预约表单)
  const [view, setView] = useState('main');
  const [activeTab, setActiveTab] = useState('Booking');
  const [hasRecord, setHasRecord] = useState(false);

  // 状态用于日历弹窗
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState('2026-01-22');

  const handleBack = () => {
    if (view === 'booking') setView('main');
    else navigate('/');
  };

  // 生成日历日期数组 (简化逻辑)
  const renderDays = () => {
    const days = [];
    for (let i = 1; i <= 31; i++) {
      days.push(
        <div key={i} className={`calendar-day ${i === 22 ? 'selected' : ''}`} onClick={() => {setSelectedDate(`2026-01-${i}`); setIsCalendarOpen(false);}}>
          {i}
        </div>
      );
    }
    return days;
  };

  return (
    <div className="transport-container">
      {/* 顶部导航栏 */}
      <nav className="top-nav-bar">
        <div className="back-arrow-wrapper" onClick={handleBack}>
          <ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} />
        </div>
        <span className="nav-title">Transport</span>
      </nav>

      <div className="scrollable-area">
        {view === 'main' ? (
          <div className="transport-content">
            {/* 顶部分类按钮 */}
            <div className="transport-tabs">
              <button className={`transport-tab-btn ${activeTab === 'Booking' ? 'active' : ''}`} onClick={() => setActiveTab('Booking')}>Booking</button>
              <button className={`transport-tab-btn ${activeTab === 'Timetable' ? 'active' : ''}`} onClick={() => setActiveTab('Timetable')}>Timetable</button>
            </div>

            {/* 空状态占位 */}
            {!hasRecord && (
              <div className="empty-state">
                <img src="/icon_img/transportation.png" alt="No Record" className="empty-image" />
                <p className="empty-text">No transport record found</p>
              </div>
            )}
          </div>
        ) : (
          /* --- 预约表单子页面 --- */
          <div className="transport-booking-form">
            <p className="booking-form-header">Need a ride? Book your shuttle in just one step!</p>
            
            <div className="booking-card">
              <div className="form-item">
                <label>Pick-up location *:</label>
                <div className="form-field-box select-type">
                  <select><option>Select Pick-up location</option></select>
                  <ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>

              <div className="form-item">
                <label>Drop-off location *:</label>
                <div className="form-field-box select-type">
                  <select><option>Select Drop-off location</option></select>
                  <ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>

              <div className="form-item">
                <label>Date:</label>
                <div className="form-field-box" onClick={() => setIsCalendarOpen(true)}>
                  <span>{selectedDate}</span>
                  <Calendar size={18} color="#666" />
                </div>
              </div>

              <div className="form-item">
                <label>Time *:</label>
                <div className="form-field-box select-type">
                  <select><option>Select Time</option></select>
                  <ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>
            </div>

            <div className="search-van-container">
              <button className="capsule-search-btn">Search Van</button>
            </div>
          </div>
        )}
      </div>

      {/* 底部按钮 (仅在 main 视图显示) */}
      {view === 'main' && (
        <div className="transport-floating-footer">
          <button className="book-room-btn" onClick={() => setView('booking')}>New Booking</button>
        </div>
      )}

      {/* 日历弹窗 */}
      {isCalendarOpen && (
        <div className="calendar-overlay">
          <div className="calendar-modal">
            <div className="calendar-modal-header">
              <span>Calendar</span>
              <button className="close-btn" onClick={() => setIsCalendarOpen(false)}><X size={20}/></button>
            </div>
            <div className="calendar-nav">
              <button className="nav-arrow">{'<'}</button>
              <span className="month-year">January 2026</span>
              <button className="nav-arrow">{'>'}</button>
            </div>
            <div className="days-grid">{renderDays()}</div>
            <button className="calendar-confirm-btn" onClick={() => setIsCalendarOpen(false)}>CONFIRM</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Transport;
